import type { CSSProperties } from 'react';
import manifest from './libraryManifest.json';
import { getEmbeddedLibrarySprites } from '../offline/embeddedAssets';
import { MOBILE_NET_INPUT_WIDTH, MOBILE_NET_INPUT_HEIGHT } from '../constants';

// The built-in example library: one sprite sheet per class in public/library/,
// generated by scripts/build-library.mjs. Each sprite is a grid of `cols` columns
// of `tile`-px square images.

export type LibraryFlag = 'best_pick' | 'likely_unfamiliar' | 'borderline' | null;

export interface LibraryClass {
  slug: string;
  name: string;
  flag: LibraryFlag;
  count: number;
  // Resolved sprite URL (a data: URL in the offline build).
  sprite: string;
}

export const LIBRARY_TILE = manifest.tile;
export const LIBRARY_COLS = manifest.cols;

let classesPromise: Promise<LibraryClass[]> | null = null;

// Best picks first, then everything else A→Z. The offline (single-file) build only
// embeds the best-pick sprites, so it only lists those.
export function getLibraryClasses(): Promise<LibraryClass[]> {
  if (!classesPromise) {
    classesPromise = getEmbeddedLibrarySprites().then((embedded) => {
      const offline = !!import.meta.env.VITE_OFFLINE_BUILD;
      return manifest.classes
        .filter((c) => !offline || embedded[c.slug])
        .map((c) => ({
          slug: c.slug,
          name: c.name,
          flag: c.flag as LibraryFlag,
          count: c.count,
          sprite: embedded[c.slug] ?? `./library/${c.slug}.jpg`,
        }))
        .sort((a, b) => {
          const pa = a.flag === 'best_pick' ? 0 : 1;
          const pb = b.flag === 'best_pick' ? 0 : 1;
          return pa - pb || a.name.localeCompare(b.name);
        });
    });
  }
  return classesPromise;
}

// CSS that shows tile `index` of a class's sprite filling a square element of any
// size, without a canvas (percentage background-position: col / (cols - 1)).
export function tileStyle(cls: LibraryClass, index: number): CSSProperties {
  const rows = Math.ceil(cls.count / LIBRARY_COLS);
  const col = index % LIBRARY_COLS;
  const row = Math.floor(index / LIBRARY_COLS);
  const pct = (n: number, total: number) => (total > 1 ? (n / (total - 1)) * 100 : 0);
  return {
    backgroundImage: `url("${cls.sprite}")`,
    backgroundSize: `${LIBRARY_COLS * 100}% ${rows * 100}%`,
    backgroundPosition: `${pct(col, LIBRARY_COLS)}% ${pct(row, rows)}%`,
  };
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load ${src}`));
    img.src = src;
  });
}

// Cuts the chosen tiles out of a class's sprite as JPEG data URLs at the model's
// input size, ready for addImageToClass().
export async function extractTiles(cls: LibraryClass, indices: number[]): Promise<string[]> {
  const img = await loadImage(cls.sprite);
  const canvas = document.createElement('canvas');
  canvas.width = MOBILE_NET_INPUT_WIDTH;
  canvas.height = MOBILE_NET_INPUT_HEIGHT;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Failed to get canvas context');
  ctx.imageSmoothingQuality = 'high';

  return indices.map((i) => {
    const sx = (i % LIBRARY_COLS) * LIBRARY_TILE;
    const sy = Math.floor(i / LIBRARY_COLS) * LIBRARY_TILE;
    ctx.drawImage(img, sx, sy, LIBRARY_TILE, LIBRARY_TILE, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.9);
  });
}

export const allTileIndices = (cls: LibraryClass) => Array.from({ length: cls.count }, (_, i) => i);
